from pathlib import Path
from decimal import Decimal,InvalidOperation
import json,pandas as pd
r=Path('/private/tmp/ipeds-post2023-audit-20260929')
read=lambda p:pd.read_csv(p,dtype=str,keep_default_na=False)
v=read(r/'varTable24.csv');codes=read(r/'valueSets24.csv')
frames={p.stem.upper():read(p) for p in r.glob('*.csv') if p.stem.upper().startswith(('HD2024','FLAGS2024','SFA','COST')) and not p.stem.startswith('sfa-variable')}
for d in [v,codes]:
 for c in ['TableName','VarName']:d[c]=d[c].str.strip().str.upper()
def norm(x):
 x=str(x).strip()
 if x=='':return ''
 try:return str(Decimal(x).normalize())
 except InvalidOperation:return x
checked=[];issues=[]
for (table,name),group in codes.groupby(['TableName','VarName']):
 if table not in frames or name not in frames[table]:continue
 vals=frames[table][name].map(norm);allowed=set(group.Codevalue.map(norm));unknown=vals[(vals!='')&~vals.isin(allowed)].value_counts().to_dict()
 checked.append({'table':table,'varname':name,'nonblank_values':int(vals.ne('').sum()),'unknown':unknown})
 if unknown:issues.append(checked[-1])
result={'scope':'All valueSets24 categories with downloaded original Access HD, FLAGS, SFA, and COST tables','category_variables_checked':len(checked),'nonblank_cells_checked':sum(c['nonblank_values'] for c in checked),'unknown_code_findings':issues}
(r/'category_code_checks.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
